// Mapea el payload de la app -> cuerpo 'emitir' de LibreDTE.
// Boleta = TipoDTE 39 (no exige receptor). Factura = 33 (receptor obligatorio).
// Con normalizar=1 LibreDTE calcula IVA/total a partir del precio neto.
const b = $json.body || $json;
const esFactura = b.tipoDTE === 33;
const enc = { IdDoc: { TipoDTE: b.tipoDTE } , Emisor: { RUTEmisor: $env.LIBREDTE_RUT_EMISOR } };
if (esFactura) {
  enc.Receptor = {
    RUTRecep: b.receptor?.rut || '',
    RznSocRecep: b.receptor?.razonSocial || '',
    GiroRecep: b.receptor?.giro || '',
    DirRecep: b.receptor?.direccion || '',
    CmnaRecep: b.receptor?.comuna || ''
  };
}
const neto = Number(b.montoNeto || b.montoTotal || 0);
const dte = {
  Encabezado: enc,
  Detalle: [ { NmbItem: 'Venta Benechito', QtyItem: 1, PrcItem: neto } ]
};
return [{ json: { documentoId: b.documentoId, tipoDTE: b.tipoDTE, dte } }];
